"use client";

import { useEffect, useRef, useState, useCallback } from "react";

export interface UseBarcodeScannerOptions {
  onScan: (barcode: string) => void | Promise<void>;
  minLength?: number; // Minimum characters for valid barcode (default 3)
  maxIntervalMs?: number; // Maximum time between keystrokes for hardware scanner (default 50ms)
  enabled?: boolean; // Toggle scanner listening
}

/**
 * MODULE 2.3.1: Hardware Barcode Scanner Listener Hook
 * Intercepts high-speed keystroke bursts generated by USB/Bluetooth barcode scanners
 * (EAN-13, UPC, Code 128, GS1 Datamatrix) and triggers instant cart auto-addition.
 */
export function useBarcodeScanner({
  onScan,
  minLength = 3,
  maxIntervalMs = 50,
  enabled = true,
}: UseBarcodeScannerOptions) {
  const [lastScanned, setLastScanned] = useState<string | null>(null);
  const [isScanning, setIsScanning] = useState(false);

  // Mutable refs to prevent unnecessary re-bindings
  const bufferRef = useRef<string>("");
  const lastKeyTimeRef = useRef<number>(0);
  const onScanRef = useRef(onScan);
  onScanRef.current = onScan;

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (!enabled) return;

      // Ignore single modifier keys
      if (["Shift", "Control", "Alt", "Meta", "CapsLock"].includes(e.key)) {
        return;
      }

      const now = Date.now();
      const elapsed = now - lastKeyTimeRef.current;
      lastKeyTimeRef.current = now;

      // Enter or Tab typically signifies end of barcode scan stream
      if (e.key === "Enter" || e.key === "Tab") {
        const potentialCode = bufferRef.current.trim();
        if (potentialCode.length >= minLength) {
          // Scanner detected! Suppress form submit or default enter behavior
          e.preventDefault();
          e.stopPropagation();

          setIsScanning(true);
          setLastScanned(potentialCode);

          Promise.resolve(onScanRef.current(potentialCode)).finally(() => {
            setIsScanning(false);
          });
        }
        bufferRef.current = "";
        return;
      }

      // Printable single character key
      if (e.key.length === 1) {
        if (elapsed > maxIntervalMs) {
          // Human speed or fresh stream, reset buffer
          bufferRef.current = e.key;
        } else {
          // Fast keystroke burst, append
          bufferRef.current += e.key;
        }
      }
    },
    [enabled, minLength, maxIntervalMs]
  );

  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("keydown", handleKeyDown, true);
    return () => {
      window.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [enabled, handleKeyDown]);

  const simulateScan = useCallback((code: string) => {
    const clean = code.trim();
    if (!clean) return;
    setLastScanned(clean);
    setIsScanning(true);
    Promise.resolve(onScanRef.current(clean)).finally(() => {
      setIsScanning(false);
    });
  }, []);

  return {
    lastScanned,
    isScanning,
    simulateScan,
  };
}
